import{_ as e,a0 as l,w as o,s as r,ao as d,I as t,x as n,a1 as p,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"探索 Linux 上的 /run | LCTT x X-CMD","titleTemplate":false,"description":"探索 Linux 上的 /run | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"探索 Linux 上的 /run | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"探索 Linux 上的 /run | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190617 Exploring -run on Linux","title":"探索 Linux 上的 /run","tag":"201906","desc":""},"relativePath":"201906/20190617 Exploring -run on Linux.md","filePath":"[post].md"}'),u={name:"201906/20190617 Exploring -run on Linux.md"};function c(h,s,g,x,k,b){const a=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="探索-linux-上的-run" tabindex="-1">探索 Linux 上的 /run <a class="header-anchor" href="#探索-linux-上的-run" aria-label="Permalink to “探索 Linux 上的 /run”">​</a></h1><blockquote><p>Linux 系统在运行时数据方面的工作方式发生了微小但重大的变化。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201906/23/092816aqczi984w30j8k12.jpg" alt=""></p><p>如果你没有密切关注，你可能没有注意到 Linux 系统在运行时数据方面的工作方式有一些小但重大的变化。 它重新组织了文件系统中可访问的方式和位置，而这个变化在大约八年前就开始了。虽然这种变化可能不足以让你的袜子变湿，但它在 Linux 文件系统中提供了更多一致性，值得进行一些探索。</p><p>要开始，请转到 <code>/run</code>。如果你使用 <code>df</code> 来检查它，你会看到这样的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -k .</span></span>
<span class="line"><span>Filesystem     1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>tmpfs             609984  2604    607380   1% /run</span></span></code></pre></div><p>它被识别为 “tmpfs”（临时文件系统），因此我们知道 <code>/run</code> 中的文件和目录没有存储在磁盘上，而只存储在内存中。它们表示保存在内存（或基于磁盘的交换空间）中的数据，它看起来像是一个已挂载的文件系统，这个可以使其更易于访问和管理。</p><p><code>/run</code> 是各种各样数据的家园。例如，如果你查看 <code>/run/user</code>，你会注意到一组带有数字名称的目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /run/user</span></span>
<span class="line"><span>1000  1002  121</span></span></code></pre></div><p>使用长文件列表可以发现这些数字的重要性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>drwx------ 5 shs  shs  120 Jun 16 12:44 1000</span></span>
<span class="line"><span>drwx------ 5 dory dory 120 Jun 16 16:14 1002</span></span>
<span class="line"><span>drwx------ 8 gdm  gdm  220 Jun 14 12:18 121</span></span></code></pre></div><p>我们看到每个目录与当前登录的用户或显示管理器 gdm 相关。数字代表他们的 UID。每个目录的内容都是运行中的进程所使用的文件。</p><p><code>/run/user</code> 文件只是你在 <code>/run</code> 中找到的一小部分。还有很多其他文件。有一些文件包含了各种系统进程的进程 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.pid</span></span>
<span class="line"><span>acpid.pid  atopacctd.pid  crond.pid  rsyslogd.pid</span></span>
<span class="line"><span>atd.pid    atop.pid       gdm3.pid   sshd.pid</span></span></code></pre></div><p>如下所示，上面列出的 <code>sshd.pid</code> 文件包含 ssh 守护程序（<code>sshd</code>）的进程 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat sshd.pid</span></span>
<span class="line"><span>1148</span></span>
<span class="line"><span>$ ps -ef | grep sshd</span></span>
<span class="line"><span>root      1148     1  0 Jun14 ?        00:00:00 /usr/sbin/sshd -D    &lt;==</span></span>
<span class="line"><span>root     10784  1148  0 12:44 ?        00:00:00 sshd: shs [priv]</span></span>
<span class="line"><span>shs      10922 10784  0 12:44 ?        00:00:00 sshd: shs@pts/0</span></span>
<span class="line"><span>root     18109  1148  0 16:13 ?        00:00:00 sshd: dory [priv]</span></span>
<span class="line"><span>dory     18232 18109  0 16:14 ?        00:00:00 sshd: dory@pts/1</span></span>
<span class="line"><span>shs      19276 10923  0 16:50 pts/0    00:00:00 grep --color=auto sshd</span></span></code></pre></div><p><code>/run</code> 中的某些子目录只能使用 root 权限访问，例如 <code>/run/sudo</code>。例如，以 root 身份运行我们可以看到一些与真实或尝试使用 <code>sudo</code> 相关的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/run/sudo/ts# ls -l</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>-rw------- 1 root dory 112 Jun 16 16:37 dory</span></span>
<span class="line"><span>-rw------- 1 root shs  168 Jun 17 08:33 shs</span></span></code></pre></div><p>为了与 <code>/run</code> 的变化保持一致，一些运行时数据的旧位置现在是符号链接。<code>/var/run</code> 现在是指向 <code>/run</code> 的指针，<code>/var/lock</code> 指向 <code>/run/lock</code> 的指针，可以保证旧的引用按预期工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var</span></span>
<span class="line"><span>total 52</span></span>
<span class="line"><span>drwxr-xr-x  2 root root     4096 Jun 17 07:36 backups</span></span>
<span class="line"><span>drwxr-xr-x 19 root root     4096 Apr 18 13:46 cache</span></span>
<span class="line"><span>drwxrwsrwt  2 root whoopsie 4096 Jun 13 07:39 crash</span></span>
<span class="line"><span>drwxr-xr-x 75 root root     4096 Jun  9 15:14 lib</span></span>
<span class="line"><span>drwxrwsr-x  2 root staff    4096 Oct 16  2017 local</span></span>
<span class="line"><span>lrwxrwxrwx  1 root root        9 May 14  2018 lock -&gt; /run/lock</span></span>
<span class="line"><span>drwxrwxr-x 17 root syslog   4096 Jun 17 00:00 log</span></span>
<span class="line"><span>drwxrwsrwt  2 root mail     4096 Jun 13 12:10 mail</span></span>
<span class="line"><span>drwxrwsrwt  2 root whoopsie 4096 Jan  5  2018 metrics</span></span>
<span class="line"><span>drwxr-xr-x  2 root root     4096 Jan  5  2018 opt</span></span>
<span class="line"><span>lrwxrwxrwx  1 root root        4 May 14  2018 run -&gt; /run</span></span>
<span class="line"><span>drwxr-xr-x  9 root root     4096 Jun 16  2018 snap</span></span>
<span class="line"><span>drwxr-xr-x  9 root root     4096 Jun  9 15:14 spool</span></span>
<span class="line"><span>drwxrwxrwt  8 root root     4096 Jun 17 00:00 tmp</span></span>
<span class="line"><span>drwxr-xr-x  3 root root     4096 Jan 19 12:14 www</span></span></code></pre></div><p>虽然技术上的变化很小，但转换到使用 <code>/run</code> 只是为了在 Linux 文件系统中更好地组织运行时数据。</p><hr>`,22)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://www.networkworld.com/article/3403023/exploring-run-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3403023/exploring-run-on-linux.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),p(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const y=e(u,[["render",c]]);export{m as __pageData,y as default};
